// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0) && rewardToken != address(c));

        // Add a reward token
        address ownerBefore = c.owner();
        c.addReward(rewardToken);

        // The general rule: owner() should return the original owner, not address(0)
        assertTrue(c.owner() == ownerBefore && c.owner() != address(0));
    }
}

